create table if not exists tenant (id bigserial primary key, code text not null unique, name text not null, default_branch_id bigint null, timezone text not null, currency text not null, country text not null, logo_url text null, status integer not null, subscription_status integer not null, created_by bigint not null, created_date timestamptz not null, modified_by bigint null, modified_date timestamptz null, deleted_by bigint null, deleted_date timestamptz null, is_deleted boolean not null default false, row_version bigint not null default 1);
create table if not exists branch (id bigserial primary key, tenant_id bigint not null references tenant(id), code text not null, name text not null, timezone text not null, country text not null, is_default boolean not null default false, status integer not null, created_by bigint not null, created_date timestamptz not null, modified_by bigint null, modified_date timestamptz null, deleted_by bigint null, deleted_date timestamptz null, is_deleted boolean not null default false, row_version bigint not null default 1, unique (tenant_id, code));
alter table tenant add constraint fk_tenant_default_branch foreign key (default_branch_id) references branch(id) deferrable initially deferred;
create table if not exists "user" (id bigserial primary key, tenant_id bigint not null references tenant(id), username text not null, email text not null, password_hash text not null, is_active boolean not null default true, language text null, timezone text null, created_by bigint not null, created_date timestamptz not null, modified_by bigint null, modified_date timestamptz null, deleted_by bigint null, deleted_date timestamptz null, is_deleted boolean not null default false, row_version bigint not null default 1, unique (tenant_id, username), unique (tenant_id, email));
create table if not exists role (id bigserial primary key, tenant_id bigint not null references tenant(id), code text not null, name text not null, is_system boolean not null default false, created_by bigint not null, created_date timestamptz not null, modified_by bigint null, modified_date timestamptz null, deleted_by bigint null, deleted_date timestamptz null, is_deleted boolean not null default false, row_version bigint not null default 1, unique (tenant_id, code));
create table if not exists permission (id bigserial primary key, code text not null unique, name text not null, resource text not null, action text not null, created_by bigint not null, created_date timestamptz not null, modified_by bigint null, modified_date timestamptz null, deleted_by bigint null, deleted_date timestamptz null, is_deleted boolean not null default false, row_version bigint not null default 1);
create table if not exists role_permission (id bigserial primary key, role_id bigint not null references role(id), permission_id bigint not null references permission(id), created_by bigint not null, created_date timestamptz not null, modified_by bigint null, modified_date timestamptz null, deleted_by bigint null, deleted_date timestamptz null, is_deleted boolean not null default false, row_version bigint not null default 1, unique (role_id, permission_id));
create table if not exists user_role (id bigserial primary key, user_id bigint not null references "user"(id), role_id bigint not null references role(id), created_by bigint not null, created_date timestamptz not null, modified_by bigint null, modified_date timestamptz null, deleted_by bigint null, deleted_date timestamptz null, is_deleted boolean not null default false, row_version bigint not null default 1, unique (user_id, role_id));
create table if not exists user_branch (id bigserial primary key, user_id bigint not null references "user"(id), branch_id bigint not null references branch(id), is_default boolean not null default false, created_by bigint not null, created_date timestamptz not null, modified_by bigint null, modified_date timestamptz null, deleted_by bigint null, deleted_date timestamptz null, is_deleted boolean not null default false, row_version bigint not null default 1, unique (user_id, branch_id));
create table if not exists refresh_token (id bigserial primary key, user_id bigint not null references "user"(id), tenant_id bigint not null references tenant(id), token_hash text not null unique, expires_at timestamptz not null, revoked_at timestamptz null, replaced_by_token_hash text null, created_by bigint not null, created_date timestamptz not null, modified_by bigint null, modified_date timestamptz null, deleted_by bigint null, deleted_date timestamptz null, is_deleted boolean not null default false, row_version bigint not null default 1);
create table if not exists password_history (id bigserial primary key, user_id bigint not null references "user"(id), password_hash text not null, created_by bigint not null, created_date timestamptz not null, modified_by bigint null, modified_date timestamptz null, deleted_by bigint null, deleted_date timestamptz null, is_deleted boolean not null default false, row_version bigint not null default 1);
create index if not exists ix_branch_tenant_id on branch(tenant_id);
create index if not exists ix_user_tenant_id on "user"(tenant_id);
create index if not exists ix_refresh_token_user_id on refresh_token(user_id);
create index if not exists ix_password_history_user_id on password_history(user_id);
